 protected void onPause(){if(chat!=null&&chat.companion!=null&&chat.companion.currentPanel!=null)chat.companion.currentPanel.onPause();if(chat!=null)chat.pause();if(runs!=null)runs.pause();if(relay!=null)relay.stop();super.onPause();}
